const prev = $('Validate Payload').first().json;
let text = '';

try {
  const ds = $input.first().json;
  text = ds.choices?.[0]?.message?.content?.trim() ?? '';
} catch (e) {
  text = '';
}

// Fallback إذا فشل DeepSeek
if (!text) {
  const o = prev.order;
  const name = o.customer_name ?? 'عميلنا الكريم';
  const store = o.store_name ?? 'المحل';
  text = `مرحباً ${name}، شكراً لزيارتكم ${store} لغيار الزيت.\n`;
  if (o.vehicle) text += `المركبة: ${o.vehicle}\n`;
  if (o.oil) text += `الزيت: ${o.oil}\n`;
  if (o.total_iqd) text += `الإجمالي: ${o.total_iqd} د.ع\n`;
  if (o.invoice_id) text += `رقم الفاتورة: ${o.invoice_id}\n`;
  text += 'نراكم عند موعد الصيانة القادمة.';
}

return [{ json: { ...prev, message_text: text, source: text ? 'deepseek' : 'fallback' } }];
